  const raw = fs.readFileSync(p, 'utf8'); const crlf = raw.includes('\r\n'); const now = raw.replace(/\r\n/g, '\n');
  if (now === f.to) { console.log('already   ' + f.file + ': ' + f.what); continue; }
  if (!f.from.includes(now)) { console.log('REFUSED   ' + f.file + ': it is not a version this patch knows, so nothing was changed. Send this file.'); problems++; continue; }
  console.log((write ? 'changing  ' : 'would     ') + f.file + ': ' + f.what);
